import { describe, test } from 'node:test';
import assert from 'node:assert/strict';

import { DivideByZeroError } from './calc.ts';
import { ParseError, evaluate } from './evaluate.ts';

describe('evaluate', () => {
  test('operator precedence: multiplication before addition', () => {
    assert.equal(evaluate('2 + 3 * 4'), 14);
  });

  test('parentheses override precedence', () => {
    assert.equal(evaluate('(2 + 3) * 4'), 20);
  });

  test('division before subtraction', () => {
    assert.equal(evaluate('10 - 4 / 2'), 8);
  });

  test('ignores embedded and mixed whitespace', () => {
    assert.equal(evaluate('  2   +   3 '), 5);
    assert.equal(evaluate('2\t+\n3'), 5);
  });

  test('nested parentheses', () => {
    assert.equal(evaluate('((2 + 3) * (4 - 1))'), 15);
  });

  test('decimal literals', () => {
    assert.equal(evaluate('1.5 + 2.5'), 4);
  });

  test('throws ParseError for incomplete input', () => {
    assert.throws(() => evaluate('2 +'), ParseError);
  });

  test('throws ParseError for unbalanced parentheses', () => {
    assert.throws(() => evaluate('(2 + 3'), ParseError);
    assert.throws(() => evaluate('2 + 3)'), ParseError);
  });

  test('throws ParseError for invalid characters', () => {
    assert.throws(() => evaluate('2 & 3'), ParseError);
  });

  test('throws ParseError for empty input', () => {
    assert.throws(() => evaluate(''), ParseError);
  });

  test('throws ParseError for unary minus', () => {
    assert.throws(() => evaluate('-5 + 1'), ParseError);
    assert.throws(() => evaluate('2 * -3'), ParseError);
  });

  test('ParseError carries the offending input', () => {
    try {
      evaluate('2 & 3');
      assert.fail('expected evaluate to throw');
    } catch (error) {
      assert.ok(error instanceof ParseError);
      assert.equal(error.input, '2 & 3');
      assert.equal(error.name, 'ParseError');
    }
  });

  test('throws DivideByZeroError, not ParseError, for division by zero', () => {
    assert.throws(() => evaluate('5 / 0'), DivideByZeroError);
  });
});

